const API="https://vkzxknpveoghhccgwaan.supabase.co/rest/v1";
const KEY="sb_publishable_N2Hxy1FWrPCbUz6ifyQx6w_fqpWal1l";
const baseHeaders={apikey:KEY,Authorization:`Bearer ${KEY}`,"Content-Type":"application/json"};
async function db(table,{method="GET",params=[],body,returning=false}={}){const qs=params.length?`?${params.join("&")}`:"";const r=await fetch(`${API}/${table}${qs}`,{method,headers:{...baseHeaders,...(returning?{Prefer:"return=representation"}:{})},body:body===undefined?undefined:JSON.stringify(body)});const t=await r.text();let d=null;try{d=t?JSON.parse(t):null}catch{d=t}if(!r.ok)throw new Error(d?.message||d?.details||d?.hint||t||`HTTP ${r.status}`);return d}
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]));
const cats={speaking:{label:"Speaking",icon:"🎙️",description:"話す練習を、自分のテーマごとに整理できます。"},listening:{label:"Listening",icon:"🎧",description:"聞き取り練習を、自分のテーマごとに整理できます。"},writing:{label:"Writing",icon:"✍️",description:"英作文・日記・添削用のタブを整理できます。"},reading:{label:"Reading",icon:"📖",description:"英文読解・記事・教材をテーマごとに整理できます。"}};
const defaults={speaking:"My Speaking",listening:"My Listening",writing:"My Writing",reading:"My Reading"};
let state={tabs:{speaking:[],listening:[],writing:[],reading:[]},activeCategory:"speaking",activeSubTabs:{}},review=null,currentArticleId=null,currentDetailId=null;
const UI_KEY="english-study-ui-v5";
function dlg(id){const e=$("#"+id);if(e&&!e.open)e.showModal()}function closeDlg(id){const e=$("#"+id);if(e?.open)e.close()}
function saveUI(){localStorage.setItem(UI_KEY,JSON.stringify({activeCategory:state.activeCategory,activeSubTabs:state.activeSubTabs}))}
function restoreUI(){try{const x=JSON.parse(localStorage.getItem(UI_KEY)||"null");if(x){state.activeCategory=x.activeCategory||"speaking";state.activeSubTabs=x.activeSubTabs||{}}}catch{}}
function tabs(){return state.tabs[state.activeCategory]||[]}function activeTab(){const t=tabs();return t.find(x=>x.id===state.activeSubTabs[state.activeCategory])||t[0]}
function showError(e){console.error(e);alert(`保存に失敗しました。\n${e.message||e}`)}
async function load(){for(const c of Object.keys(cats)){let rows=await db("study_tabs",{params:[`category=eq.${encodeURIComponent(c)}`,"select=id,name,category,created_at","order=created_at.asc"]});if(!rows.length)rows=await db("study_tabs",{method:"POST",body:{category:c,name:defaults[c]},returning:true});state.tabs[c]=rows;if(c==="reading")rows.forEach(t=>t.articles=[])}
const articles=await db("reading_articles",{params:["select=id,tab_id,title,url,memo,article_date,english_text,japanese_translation,grammar_notes,created_at","order=created_at.desc"]});
const items=await db("learning_items",{params:["select=id,article_id,term,meaning,how,example,context,level,last_reviewed,created_at","order=created_at.asc"]});
const map=new Map(articles.map(a=>[a.id,{id:a.id,title:a.title,url:a.url||"",memo:a.memo||"",date:a.article_date||"",englishText:a.english_text||"",translation:a.japanese_translation||"",grammar:a.grammar_notes||"",items:[]} ]));
items.forEach(x=>map.get(x.article_id)?.items.push({id:x.id,term:x.term,meaning:x.meaning,how:x.how||"",example:x.example||"",context:x.context||"",level:x.level||0,lastReviewed:x.last_reviewed}));
state.tabs.reading.forEach(t=>t.articles=articles.filter(a=>a.tab_id===t.id).map(a=>map.get(a.id)).filter(Boolean));restoreUI();for(const c of Object.keys(cats)){if(!state.tabs[c].some(t=>t.id===state.activeSubTabs[c]))state.activeSubTabs[c]=state.tabs[c][0]?.id}render()}
function render(){ $$(".main-tab").forEach(b=>b.classList.toggle("active",b.dataset.mainTab===state.activeCategory));const list=$("#subTabs");list.innerHTML="";const ts=tabs(),at=activeTab();ts.forEach(t=>{const b=document.createElement("button");b.type="button";b.className=`sub-tab${t.id===at?.id?" active":""}`;b.innerHTML=`<span>${esc(t.name)}</span>`;if(ts.length>1){const x=document.createElement("button");x.type="button";x.className="close-sub";x.textContent="×";x.onclick=e=>{e.stopPropagation();removeTab(t.id)};b.appendChild(x)}b.onclick=()=>{state.activeSubTabs[state.activeCategory]=t.id;saveUI();render()};list.appendChild(b)});
const c=cats[state.activeCategory];$("#workspaceKicker").textContent=c.label.toUpperCase();$("#workspaceTitle").textContent=c.label;$("#contentIcon").textContent=c.icon;$("#contentTitle").textContent=`${at?.name||c.label} を始めよう`;$("#contentDescription").textContent=c.description;
const reading=state.activeCategory==="reading";$("#genericContent").classList.toggle("hidden",reading);$("#readingContent").classList.toggle("hidden",!reading);$("#newArticleHeaderButton").classList.toggle("hidden",!reading);if(reading&&at){$("#readingTabTitle").textContent=at.name;const as=at.articles||[];$("#readingEmpty").classList.toggle("hidden",as.length>0);const box=$("#articleList");box.innerHTML="";as.forEach(a=>{const n=a.items?.length||0,card=document.createElement("article");card.className="article-card";card.innerHTML=`<div class="article-card-top"><div><span class="article-date">${esc(a.date)}</span><h4>${esc(a.title)}</h4><p>${esc(a.memo)}</p></div><span class="article-count">${n} items</span></div><div class="article-actions">${a.url?`<a class="secondary-button link-button" href="${esc(a.url)}" target="_blank" rel="noopener">BBC記事 ↗</a>`:""}<button class="new-button" data-open="${a.id}">学習ページを開く</button><button class="secondary-button" data-bundle="${a.id}">ChatGPT一括登録</button></div>`;box.appendChild(card)})}
$("#tabCount").textContent=Object.values(state.tabs).reduce((n,x)=>n+x.length,0);$("#studyMinutes").innerHTML=`${state.tabs.reading.reduce((n,t)=>n+(t.articles||[]).reduce((m,a)=>m+(a.items?.length||0),0),0)} <small>items</small>`}
async function addTab(){const c=state.activeCategory,name=prompt(`${cats[c].label} に追加するタブ名`,c==="reading"?"BBC News":"New lesson");if(!name?.trim())return;try{const [t]=await db("study_tabs",{method:"POST",body:{category:c,name:name.trim()},returning:true});if(c==="reading")t.articles=[];state.tabs[c].push(t);state.activeSubTabs[c]=t.id;saveUI();render()}catch(e){showError(e)}}
async function removeTab(id){const ts=tabs();if(ts.length<=1)return;const t=ts.find(x=>x.id===id);if(!t||!confirm(`「${t.name}」を削除しますか？`))return;try{await db("study_tabs",{method:"DELETE",params:[`id=eq.${encodeURIComponent(id)}`]});const i=ts.indexOf(t);ts.splice(i,1);state.activeSubTabs[state.activeCategory]=ts[Math.max(0,i-1)].id;saveUI();render()}catch(e){showError(e)}}
function openArticle(){ $("#articleForm").reset();dlg("articleDialog");$("#articleTitle").focus() }
async function saveArticle(e){e.preventDefault();const t=activeTab();try{const [a]=await db("reading_articles",{method:"POST",body:{tab_id:t.id,title:$("#articleTitle").value.trim(),url:$("#articleUrl").value.trim()||null,memo:$("#articleMemo").value.trim()||null},returning:true});t.articles||=[];t.articles.unshift({id:a.id,title:a.title,url:a.url||"",memo:a.memo||"",date:a.article_date||"",englishText:"",translation:"",grammar:"",items:[]});closeDlg("articleDialog");render()}catch(e){showError(e)}}
function findArticle(id){for(const t of state.tabs.reading){const a=(t.articles||[]).find(x=>x.id===id);if(a)return a}return null}
function parseBundle(text){const norm=text.replace(/\r/g,"");const sections={};const re=/【(英文|翻訳|単語・表現|文法・構文)】/g;let m,last=null,lastPos=0;while((m=re.exec(norm))){if(last)sections[last]=norm.slice(lastPos,m.index).trim();last=m[1];lastPos=re.lastIndex}if(last)sections[last]=norm.slice(lastPos).trim();const vocab=(sections["単語・表現"]||"").split(/\n+/).map(x=>x.trim()).filter(Boolean).filter(x=>!/^[-|\s]*$/.test(x)).map(line=>{const p=line.split(/\t|\s*\|\s*/).map(x=>x.trim()).filter(Boolean);if(p[0]?.includes("単語")&&p[1]?.includes("意味"))return null;return p.length>=2?{term:p[0],meaning:p[1],context:p[2]||"",how:p[3]||"",example:p[4]||""}:null}).filter(Boolean);return{english:sections["英文"]||"",translation:sections["翻訳"]||"",grammar:sections["文法・構文"]||"",vocab}}
async function saveBundle(e){e.preventDefault();const a=findArticle(currentArticleId);if(!a)return;const parsed=parseBundle($("#bundleInput").value);if(!parsed.english&&!parsed.translation&&!parsed.grammar&&!parsed.vocab.length)return alert("【英文】【翻訳】【単語・表現】【文法・構文】の見出し付きで貼り付けてください。");try{await db("reading_articles",{method:"PATCH",params:[`id=eq.${encodeURIComponent(a.id)}`],body:{english_text:parsed.english||null,japanese_translation:parsed.translation||null,grammar_notes:parsed.grammar||null}});a.englishText=parsed.english;a.translation=parsed.translation;a.grammar=parsed.grammar;if(parsed.vocab.length){const data=await db("learning_items",{method:"POST",body:parsed.vocab.map(v=>({article_id:a.id,term:v.term,meaning:v.meaning,context:v.context||null,how:v.how||null,example:v.example||null})),returning:true});a.items.push(...data.map(x=>({id:x.id,term:x.term,meaning:x.meaning,context:x.context||"",how:x.how||"",example:x.example||"",level:x.level||0,lastReviewed:x.last_reviewed})))}closeDlg("bundleDialog");render();openDetail(a.id)}catch(e){showError(e)}}
function openDetail(id){const a=findArticle(id);if(!a)return;currentDetailId=id;$("#detailTitle").textContent=a.title;$("#detailSource").innerHTML=a.url?`<a href="${esc(a.url)}" target="_blank" rel="noopener">BBC記事を開く ↗</a>`:"";drawDetailTab("english");dlg("detailDialog")}
function drawDetailTab(tab){const a=findArticle(currentDetailId);$$(".detail-tab").forEach(b=>b.classList.toggle("active",b.dataset.detailTab===tab));const body=$("#detailBody");if(tab==="english")body.innerHTML=`<div class="reading-text">${a.englishText?esc(a.englishText).replace(/\n/g,"<br>"):"まだ英文が登録されていません。"}</div>`;if(tab==="translation")body.innerHTML=`<div class="reading-text">${a.translation?esc(a.translation).replace(/\n/g,"<br>"):"まだ翻訳が登録されていません。"}</div>`;if(tab==="vocab")body.innerHTML=a.items.length?`<div class="vocab-table"><div class="vocab-row head"><span>単語・表現</span><span>意味</span><span>記事中の使われ方</span></div>${a.items.map(x=>`<div class="vocab-row"><strong>${esc(x.term)}</strong><span>${esc(x.meaning)}</span><span>${esc(x.context||x.example||"")}</span></div>`).join("")}</div>`:`<p class="empty-note">まだ単語・表現がありません。</p>`;if(tab==="grammar")body.innerHTML=`<div class="grammar-text">${a.grammar?esc(a.grammar).replace(/\n/g,"<br>"):"まだ文法・構文が登録されていません。"}</div>`}

$("#newTabButton").onclick=addTab;$$('.main-tab').forEach(b=>b.onclick=()=>{state.activeCategory=b.dataset.mainTab;saveUI();render()});$$('[data-close]').forEach(b=>b.onclick=()=>closeDlg(b.dataset.close));$("#newArticleButton").onclick=openArticle;$("#newArticleHeaderButton").onclick=openArticle;$("#articleForm").onsubmit=saveArticle;$("#bundleForm").onsubmit=saveBundle;$("#articleList").onclick=e=>{const open=e.target.closest('[data-open]')?.dataset.open,bundle=e.target.closest('[data-bundle]')?.dataset.bundle;if(open)openDetail(open);if(bundle){currentArticleId=bundle;$("#bundleInput").value="";dlg("bundleDialog");$("#bundleInput").focus()}};$$('.detail-tab').forEach(b=>b.onclick=()=>drawDetailTab(b.dataset.detailTab));
try{await load()}catch(e){console.error(e);state.tabs={speaking:[{id:"offline-speaking",name:defaults.speaking}],listening:[{id:"offline-listening",name:defaults.listening}],writing:[{id:"offline-writing",name:defaults.writing}],reading:[{id:"offline-reading",name:defaults.reading,articles:[]}]};restoreUI();Object.keys(cats).forEach(c=>state.activeSubTabs[c]||=state.tabs[c][0].id);render()}
